import { sql } from 'drizzle-orm';
import { bigint, boolean, char, check, text, timestamp } from 'drizzle-orm/pg-core';

/**
 * Shared building blocks for the canonical agricultural schema (Phase 2, Milestone 2.1).
 *
 * Naming conventions: snake_case columns, `<table>_<what>_<kind>` constraint and index names
 * (kept under PostgreSQL's 63-character identifier limit), UUID primary keys generated by the
 * database, `timestamptz` for instants and `date` for observation days.
 */

/**
 * Minimal, deterministic normalisation used to compare names: collapse runs of whitespace,
 * trim, lower-case. It deliberately does NOT repair spelling or merge variants: spelling
 * variants are resolved explicitly through the alias tables, never by fuzzy matching.
 *
 * @param {string} column Name of the column to normalise.
 */
export const normalizedNameSql = (column) =>
  sql.raw(`lower(btrim(regexp_replace("${column}", '\\s+', ' ', 'g')))`);

/** A generated, always-consistent normalised copy of a name column. */
export const normalizedNameColumn = (column, source) =>
  text(column).notNull().generatedAlwaysAs(normalizedNameSql(source));

/** SQL list literal for CHECK ... IN (...) constraints. */
export const inList = (values) => sql.raw(values.map((v) => `'${v}'`).join(', '));

/** Allowed first date of any observation, and a ceiling that rejects typos (year 2099 etc.). */
export const OBSERVATION_MIN_DATE = '1990-01-01';
export const OBSERVATION_MAX_DATE = '2100-12-31';

export const QUALITY_STATUSES = /** @type {const} */ (['accepted', 'flagged']);

/**
 * Quality columns shared by every fact table. `rejected` records never enter a fact table; they
 * are quarantined in `ingestion_rejections` with their raw values.
 */
export const qualityColumns = () => ({
  qualityStatus: text('quality_status').notNull().default('accepted'),
  qualityFlags: text('quality_flags')
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
});

/**
 * Columns recording where a fact came from and how it was loaded. Together with the composite
 * foreign keys declared by each table they make every row traceable to one ingestion run, one
 * source and (when it came from a file) one registered file.
 */
export const provenanceColumns = () => ({
  sourceRecordKey: text('source_record_key').notNull(),
  sourceRowNumber: bigint('source_row_number', { mode: 'number' }),
  recordFingerprint: char('record_fingerprint', { length: 64 }).notNull(),
  sourcePublishedAt: timestamp('source_published_at', { withTimezone: true }),
  ingestedAt: timestamp('ingested_at', { withTimezone: true }).notNull().defaultNow(),
  isHistoricalSnapshot: boolean('is_historical_snapshot').notNull().default(false),
  isSynthetic: boolean('is_synthetic').notNull().default(false),
});

/**
 * Checks shared by every fact table.
 *
 * @param {string} prefix Table-specific constraint-name prefix.
 * @param {Record<string, any>} t Table columns.
 */
export const factChecks = (prefix, t) => [
  check(`${prefix}_quality_status_ck`, sql`${t.qualityStatus} IN ('accepted', 'flagged')`),
  // A record is "flagged" exactly when it carries at least one flag.
  check(
    `${prefix}_quality_flags_ck`,
    sql`(${t.qualityStatus} = 'flagged') = (cardinality(${t.qualityFlags}) > 0)`,
  ),
  check(`${prefix}_fingerprint_ck`, sql`${t.recordFingerprint} ~ '^[0-9a-f]{64}$'`),
  check(`${prefix}_record_key_ck`, sql`btrim(${t.sourceRecordKey}) <> ''`),
];
